// Evolution API manda el mensaje en body.data.
// Ajusta estas rutas si tu versión de Evolution usa otro formato
// (revisa una ejecución real en n8n: "Executions" > abrir > ver el JSON).
const body = $input.first().json.body || $input.first().json;
const data = body.data || body;

const remoteJid = data?.key?.remoteJid || data?.from || '';
const phone = remoteJid.replace('@s.whatsapp.net', '').replace(/\D/g, '');

const text =
  data?.message?.conversation ||
  data?.message?.extendedTextMessage?.text ||
  data?.body ||
  '';

if (!phone || !text) {
  return [];
}

return [{ json: { phone, text: text.trim() } }];

const query = $('Extraer teléfono y texto').first().json.text;
const phone = $('Extraer teléfono y texto').first().json.phone;
const products = $input.first().json.products || [];
const baseUrl = $env.STOREFRONT_URL || 'https://hetnacnc.com';

let reply;
if (!products.length) {
  reply = `No encontré productos para "${query}" 😕. ¿Puedes describirlo de otra forma (material, tamaño, tipo de pieza)?`;
} else {
  const lines = products.slice(0, 5).map((p) => {
    const amount = p.variants?.[0]?.calculated_price?.calculated_amount;
    const currency = p.variants?.[0]?.calculated_price?.currency_code?.toUpperCase();
    const price = amount != null ? `$${amount} ${currency}` : 'Consultar precio';
    return `• ${p.title} — ${price}\n  ${baseUrl}/mx/products/${p.handle}`;
  });
  reply = `Encontré esto para "${query}":\n\n${lines.join('\n\n')}\n\n¿Quieres que te ayude con alguno?`;
}

return [{ json: { phone, reply } }];
